changeSet.sql:
DO $$ DECLARE snapshot_hash CONSTANT VARCHAR(64) := '9e4d2a035daf0d21944ef21684a467d26349023e2b2c56e30ffc98385bc56282'; BEGIN UPDATE credesal_gl_account_presentation_seed_0337 SET source_parent_account_id = NULLIF(BTRIM(source_parent_account_id), ''), parent_gl_code = NULLIF(BTRIM(parent_gl_code), '');
IF (SELECT COUNT(*) FROM credesal_gl_account_presentation_seed_0337) <> 2494 OR (SELECT COUNT(DISTINCT gl_code) FROM credesal_gl_account_presentation_seed_0337) <> 2494 OR (SELECT COUNT(*) FROM credesal_gl_account_presentation_seed_0337 WHERE trial_balance_selected) <> 101 OR (SELECT COUNT(*) FROM credesal_gl_account_presentation_seed_0337 WHERE balance_sheet_selected) <> 75 OR (SELECT COUNT(*) FROM credesal_gl_account_presentation_seed_0337 WHERE balance_sheet_selected AND classifier_code IN ('001', '002', '003')) <> 64 OR (SELECT COUNT(*) FROM credesal_gl_account_presentation_seed_0337 WHERE balance_sheet_selected AND classifier_code IN ('006', '007')) <> 11 OR (SELECT COUNT(*) FROM credesal_gl_account_presentation_seed_0337 WHERE trial_balance_selected AND NOT balance_sheet_selected AND classifier_code IN ('004', '005')) <> 26 THEN RAISE EXCEPTION 'Credesal GL presentation snapshot failed frozen selector counts'; END IF;
IF EXISTS ( SELECT 1 FROM credesal_gl_account_presentation_seed_0337 source LEFT JOIN credesal_gl_account_presentation_seed_0337 parent ON parent.gl_code = source.parent_gl_code WHERE source.balance_nature NOT IN ('D', 'A') OR (source.source_parent_account_id IS NULL) <> (source.parent_gl_code IS NULL) OR (source.parent_gl_code IS NOT NULL AND parent.gl_code IS NULL) ) THEN RAISE EXCEPTION 'Credesal GL presentation snapshot has invalid nature or parent hierarchy'; END IF;
-- The 12 source codes absent from migration 0310 are non-selected legacy -- posting leaves. Every selected report rollup must map exactly by code. IF EXISTS ( SELECT 1 FROM credesal_gl_account_presentation_seed_0337 source LEFT JOIN acc_gl_account target ON target.gl_code = source.gl_code WHERE source.trial_balance_selected AND target.id IS NULL ) THEN RAISE EXCEPTION 'A selected Credesal report account is missing from the native COA'; END IF;
INSERT INTO credesal_gl_account_presentation ( gl_account_id, presentation_version, source_snapshot_sha256, source_account_id, source_gl_code, source_name, source_parent_account_id, source_parent_gl_code, classifier_code, classifier_name, trial_balance_group, trial_balance_order, income_statement_order, account_order, balance_nature, trial_balance_selected, balance_sheet_selected ) SELECT target.id, 'arissto-coa-presentation-v1', snapshot_hash, source.source_account_id, source.gl_code, source.source_name, source.source_parent_account_id, source.parent_gl_code, source.classifier_code, source.classifier_name, source.trial_balance_group, source.trial_balance_order, source.income_statement_order, source.account_order, source.balance_nature, source.trial_balance_selected, source.balance_sheet_selected FROM credesal_gl_account_presentation_seed_0337 source JOIN acc_gl_account target ON target.gl_code = source.gl_code;
IF (SELECT COUNT(*) FROM credesal_gl_account_presentation) <> 2482 OR (SELECT COUNT(*) FROM credesal_gl_account_presentation WHERE trial_balance_selected) <> 101 OR (SELECT COUNT(*) FROM credesal_gl_account_presentation WHERE balance_sheet_selected) <> 75 OR EXISTS ( SELECT 1 FROM credesal_gl_account_presentation presentation JOIN acc_gl_account target ON target.id = presentation.gl_account_id LEFT JOIN acc_gl_account target_parent ON target_parent.id = target.parent_id WHERE target.gl_code IS DISTINCT FROM presentation.source_gl_code OR target_parent.gl_code IS DISTINCT FROM presentation.source_parent_gl_code ) THEN RAISE EXCEPTION 'Credesal GL presentation metadata did not reconcile to the native COA'; END IF; END $$;
